import { agent, s, workflow } from "rig";
import { readFileSync } from "node:fs";

type Pr = { number: number; title: string; body?: string };

// Agent role: design discriminating yes/no questions from the list of PR titles.
const designQuestions = agent({
  name: "designQuestions",
  model: "small",
  input: s.object({ titles: s.string }),
  output: s.object({ questions: s.array(s.string) }),
  instructions:
    "Each line is 'number | title' of a merged PR in one repository. Write exactly 10 short, mutually independent yes/no questions that, answered per PR, would best separate these PRs into distinct themes (e.g. 'Does this PR change dependency versions?'). Each question must be answerable from a title plus short excerpt, cover a different theme, and be true for several but not most PRs.",
});

// Agent role: answer every question for each PR in a batch.
const answerQuestions = agent({
  name: "answerQuestions",
  model: "small",
  input: s.object({ questions: s.string, prs: s.string }),
  output: s.object({ items: s.array(s.object({ pr: s.int, answers: s.array(s.boolean) })) }),
  instructions:
    "Questions are numbered lines. Each PR line is 'number | title | body excerpt'. For every listed PR return one item whose answers array has exactly one boolean per question, in question order. Use only listed numbers, each exactly once.",
});

// Agent role: name a cluster from its member PRs.
const describeCluster = agent({
  name: "describeCluster",
  model: "small",
  input: s.object({ members: s.string }),
  output: s.object({ label: s.string, summary: s.string }),
  instructions:
    "Each line is 'number | title'. Return a short thematic label (max 6 words) and a one-sentence summary grounded only in these titles.",
});

const clean = (t = "") => t.replace(/https?:\S+/g, "").replace(/\s+/g, " ").trim();
const NQ = 10;

// Workflow role: yes/no question signatures per PR, deterministic Hamming-distance grouping, cluster naming, validation.
export default workflow({
  meta: {
    name: "question-signature-hamming-groups",
    description: "Model designs discriminating questions, answers them per PR into binary signatures, TypeScript groups by Hamming distance",
    phases: ["Questions", "Answer", "Group", "Describe", "Validate"],
  },
  body: async ({ call, phase }) => {
    const corpus = JSON.parse(readFileSync("/tmp/gh-aw/agent/merged-prs.json", "utf8"));
    const prs: Pr[] = [...corpus.prs].sort((a: Pr, b: Pr) => a.number - b.number);
    const byNum = new Map(prs.map((p) => [p.number, p]));
    if (prs.length === 0 || byNum.size !== prs.length) throw new Error("bad corpus");

    phase("Questions");
    const q = await call(designQuestions, { titles: prs.map((p) => `${p.number} | ${p.title}`).join("\n") }, { label: "questions" });
    if (!q || q.questions.length !== NQ || q.questions.some((x) => !x.trim())) throw new Error("malformed question set");
    const qText = q.questions.map((x, i) => `${i + 1}. ${x}`).join("\n");

    phase("Answer");
    const batches: Pr[][] = [];
    for (let i = 0; i < prs.length; i += 5) batches.push(prs.slice(i, i + 5));
    if (batches.length > 20) throw new Error("too many batches");
    const sig = new Map<number, boolean[]>();
    for (let g = 0; g < batches.length; g += 3) {
      const group = batches.slice(g, g + 3);
      const res = await Promise.all(
        group.map((b, i) =>
          call(answerQuestions, { questions: qText, prs: b.map((p) => `${p.number} | ${p.title} | ${clean(p.body).slice(0, 250)}`).join("\n") }, { label: `answer${g + i}` }),
        ),
      );
      res.forEach((r, i) => {
        if (!r) throw new Error(`missing answer response ${g + i}`);
        const want = new Set(group[i].map((p) => p.number));
        for (const it of r.items) {
          if (!want.has(it.pr) || sig.has(it.pr) || it.answers.length !== NQ) throw new Error(`invalid answer for PR ${it.pr}`);
          sig.set(it.pr, it.answers);
        }
        if (group[i].some((p) => !sig.has(p.number))) throw new Error(`batch ${g + i}: incomplete coverage`);
      });
    }

    phase("Group");
    const ham = (a: number, b: number) => sig.get(a)!.reduce((t, x, k) => t + (x === sig.get(b)![k] ? 0 : 1), 0);
    const unclassified: { pr: number; reason: string }[] = [];
    const bySig = new Map<string, number[]>();
    for (const p of prs) {
      const key = sig.get(p.number)!.map((x) => (x ? 1 : 0)).join("");
      if (!key.includes("1")) {
        unclassified.push({ pr: p.number, reason: "Answered no to every discriminating question" });
        continue;
      }
      bySig.set(key, [...(bySig.get(key) ?? []), p.number]);
    }
    let groups = [...bySig.values()];
    const MAXAVG = 1;
    for (;;) {
      let best = Infinity;
      let bi = 0;
      let bj = 0;
      for (let i = 0; i < groups.length; i++)
        for (let j = i + 1; j < groups.length; j++) {
          let t = 0;
          for (const a of groups[i]) for (const b of groups[j]) t += ham(a, b);
          const avg = t / (groups[i].length * groups[j].length);
          if (avg < best) {
            best = avg;
            bi = i;
            bj = j;
          }
        }
      if (best > MAXAVG) break;
      groups = groups.filter((_, k) => k !== bi && k !== bj).concat([[...groups[bi], ...groups[bj]]]);
    }
    const multi = groups.filter((g) => g.length >= 2).map((g) => [...g].sort((a, b) => a - b));
    for (const g of groups.filter((x) => x.length === 1))
      unclassified.push({ pr: g[0], reason: `No other PR within average Hamming distance ${MAXAVG} on ${NQ} question answers` });
    unclassified.sort((a, b) => a.pr - b.pr);

    phase("Describe");
    if (1 + batches.length + multi.length > 38) throw new Error("call budget exceeded");
    const described: ({ label: string; summary: string } | null)[] = [];
    for (let g = 0; g < multi.length; g += 3) {
      const res = await Promise.all(
        multi.slice(g, g + 3).map((m, i) =>
          call(describeCluster, { members: m.map((n) => `${n} | ${byNum.get(n)!.title}`).join("\n") }, { label: `describe${g + i}` }),
        ),
      );
      described.push(...res);
    }
    const clusters = multi
      .map((m, i) => {
        const d = described[i];
        if (!d || !d.label.trim() || !d.summary.trim()) throw new Error("missing cluster description");
        return { id: `q${String(m[0]).padStart(5, "0")}`, label: d.label, summary: d.summary, prs: m, size: m.length };
      })
      .sort((x, y) => y.size - x.size || x.id.localeCompare(y.id));

    phase("Validate");
    const seen = new Set<number>();
    for (const n of [...clusters.flatMap((c) => c.prs), ...unclassified.map((u) => u.pr)]) {
      if (!byNum.has(n) || seen.has(n)) throw new Error(`invalid or duplicate PR ${n}`);
      seen.add(n);
    }
    if (seen.size !== prs.length) throw new Error("incomplete coverage");
    if (new Set(clusters.map((c) => c.id)).size !== clusters.length) throw new Error("duplicate cluster id");

    return {
      repository: corpus.repository,
      window: corpus.window,
      strategy: `Model-designed ${NQ} yes/no discriminating questions, per-PR binary answer signatures, TypeScript average-Hamming agglomeration (<= ${MAXAVG}), cluster naming`,
      questions: q.questions,
      totalPrs: prs.length,
      modelCalls: 1 + batches.length + multi.length,
      clusters,
      topThree: clusters.slice(0, 3).map((c) => c.id),
      unclassified,
    };
  },
});
